#!/usr/bin/env bash\n\nset -euo pipefail\n\n# Array of whimsical apocalypse messages\nAPOC_MESSAGES=(\n  "⚠️ The end is near! Disk space dwindles."\n  "💀 Your storage is haunted by ghosts of files past."\n  "🔥 The server is ablaze with data!"\n  "🌪️ A data storm approaches!"\n  "🧟‍♂️ Zombies are crawling out of the full disk."\n)\n\n# Retrieve the usage percentage of the root filesystem (without the % sign)\nfunction get_usage() {\n  df -h / | awk 'NR==2 {gsub("%","",$5); print $5}'\n}\n\n# Emit warning or success message\nfunction warn() {\n  local usage=$1\n  local threshold=$2\n  if (( usage >= threshold )); then\n    # In test mode (DISK_GUARDIAN_TEST=1) pick the first message for determinism\n    if [[ "${DISK_GUARDIAN_TEST:-0}" == "1" ]]; then\n      local msg="${APOC_MESSAGES[0]}"\n    else\n      local msg="${APOC_MESSAGES[$RANDOM % ${#APOC_MESSAGES[@]}]}"\n    fi\n    echo "🚨 Disk usage ${usage}% exceeds threshold ${threshold}%."\n    echo "$msg"\n    exit 1\n  else\n    echo "✅ Disk usage ${usage}% is within safe limits (${threshold}%)."\n  fi\n}\n\nfunction main() {\n  local threshold=${1:-80}\n  if ! [[ "$threshold" =~ ^[0-9]+$ ]]; then\n    echo "Threshold must be an integer."\n    exit 2\n  fi\n  local usage\n  usage=$(get_usage)\n  warn "$usage" "$threshold"\n}\n\n# Execute when run directly\nif [[ "${BASH_SOURCE[0]}" == "${0}" ]]; then\n  main "$@"\nfi\n
